// AES-256-CBC encrypt/decrypt of the UPM container file.
// File layout + crypto: doc/crypto.md.

import { asBufferSource, concat } from '../util/bytes';
import {
  InvalidPasswordError,
  NotAPasswordDatabaseError,
  UnsupportedVersionError,
} from './errors';
import { deriveKeyAndIv } from './kdf';

/** The ASCII bytes `UPM` that start every modern database file. */
const MAGIC = new Uint8Array([0x55, 0x50, 0x4d]);

/** Header length: `UPM` (3) + version (1) + salt (8). */
const HEADER_LENGTH = 12;

/** Salt length in bytes (`EncryptionService.SALT_LENGTH`). */
export const SALT_LENGTH = 8;

/** Versions this implementation can read (v2 = default charset, v3 = UTF-8). */
const SUPPORTED_VERSIONS = new Set([2, 3]);

/** True when `bytes` starts with the `UPM` magic. */
export function isPasswordDatabase(bytes: Uint8Array): boolean {
  return (
    bytes.length >= 3 &&
    bytes[0] === MAGIC[0] &&
    bytes[1] === MAGIC[1] &&
    bytes[2] === MAGIC[2]
  );
}

/**
 * Version byte of a UPM file (byte 3). Throws `NotAPasswordDatabaseError` when
 * the magic is missing, `UnsupportedVersionError` for unknown versions.
 */
export function databaseVersion(bytes: Uint8Array): number {
  return readHeader(bytes).version;
}

/** A fresh random 8-byte salt for a new database. */
export function newSalt(): Uint8Array {
  return crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
}

/** Validate the header and return the version + salt. */
function readHeader(bytes: Uint8Array): { version: number; salt: Uint8Array } {
  if (!isPasswordDatabase(bytes) || bytes.length < HEADER_LENGTH) {
    throw new NotAPasswordDatabaseError();
  }
  const version = bytes[3];
  if (!SUPPORTED_VERSIONS.has(version)) {
    throw new UnsupportedVersionError(
      `Unsupported password database version: 0x${version.toString(16).padStart(2, '0')}`,
    );
  }
  return { version, salt: bytes.slice(4, HEADER_LENGTH) };
}

/** True when `err` is the WebCrypto failure caused by bad PKCS#7 padding. */
function isCryptoFailure(err: unknown): boolean {
  if (err instanceof DOMException) {
    return true;
  }
  return (
    typeof err === 'object' &&
    err !== null &&
    (err as { name?: unknown }).name === 'OperationError'
  );
}

/**
 * Decrypt a UPM database file with the master password and return the raw
 * decrypted payload (the flat-packed field stream). A wrong password surfaces
 * as `InvalidPasswordError`.
 */
export async function decryptDatabase(
  bytes: Uint8Array,
  password: string,
): Promise<Uint8Array> {
  const { salt } = readHeader(bytes);
  const ciphertext = bytes.slice(HEADER_LENGTH);
  const { key, iv } = await deriveKeyAndIv(password, salt);
  try {
    const plaintext = await crypto.subtle.decrypt(
      { name: 'AES-CBC', iv: asBufferSource(iv) },
      key,
      asBufferSource(ciphertext),
    );
    return new Uint8Array(plaintext);
  } catch (err) {
    if (isCryptoFailure(err)) {
      throw new InvalidPasswordError();
    }
    throw err;
  }
}

/**
 * Encrypt a payload into a UPM **v3** database file with the given 8-byte salt
 * (`UPM` + `0x03` + salt + AES-256-CBC ciphertext).
 */
export async function encryptDatabase(
  payload: Uint8Array,
  password: string,
  salt: Uint8Array,
): Promise<Uint8Array> {
  if (salt.length !== SALT_LENGTH) {
    throw new Error(`Salt must be ${SALT_LENGTH} bytes, got ${salt.length}`);
  }
  const { key, iv } = await deriveKeyAndIv(password, salt);
  const ciphertext = new Uint8Array(
    await crypto.subtle.encrypt(
      { name: 'AES-CBC', iv: asBufferSource(iv) },
      key,
      asBufferSource(payload),
    ),
  );
  return concat(new Uint8Array([0x55, 0x50, 0x4d, 0x03]), salt, ciphertext);
}
